import collections

def simulate_spread(steps):
    # Start with a single cell at (0, 0)
    flooded = {(0, 0)}

    for _ in range(steps):
        newly_flooded = set()
        for x, y in flooded:
            # Check 4 neighbors
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in flooded:
                    newly_flooded.add((nx, ny))
        flooded.update(newly_flooded)

    # Calculate area and perimeter
    area = len(flooded)
    perimeter = 0

    for x, y in flooded:
        # Count edges on the boundary
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in flooded:
                perimeter += 1

    return area, perimeter

# Test for several steps
results = {}
for n in range(1, 10):
    area, perimeter = simulate_spread(n)
    results[n] = (area, perimeter)

print("N | Area | Perimeter")
for n, (area, perimeter) in results.items():
    print(f"{n} | {area} | {perimeter}")
